INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'cuento-colectivo', 'Cuento Colectivo', 'Dinámica de improvisación narrativa y relato encadenado donde los scouts inventan una historia épica de campamento.', '<h2>📜 Descripción de Cuento Colectivo</h2>
<p><b>Cuento Colectivo</b> es una dinámica de improvisación narrativa oral, rápida asociación de ideas y pertenencia afectiva. Ideal para tardes de campamento, jornadas lluviosas en la sede o alrededor del fuego en la fogata nocturna, esta actividad invita a la patrulla a construir en tiempo real una historia fantástica o de aventuras scout de forma totalmente improvisada.</p>
<p>Los participantes se sientan en círculo. Al centro se dispone un mazo de tarjetas de cartulina que contienen conceptos, objetos scouts, personajes misteriosos o dilemas morales (ej. <i>''Un pañolín dorado''</i>, <i>''La brújula que apuntaba al sur''</i>, <i>''El Guardián del Bosque''</i> o <i>''Una clave secreta borrada por la lluvia''</i>). El primer scout toma una tarjeta y arranca el relato introduciendo el escenario y al protagonista en dos o tres oraciones. A continuación, el participante de al lado roba la siguiente tarjeta y debe continuar la trama sin pausar el ritmo, integrando de forma lógica y divertida su nuevo elemento. La historia evoluciona de manera impredecible a través de las ocurrencias de cada scout hasta que el último integrante debe tejer un final heroico que resuelva los nudos de la aventura.</p>
<p>Esta dinámica estimula la fluidez verbal, la capacidad de escuchar al compañero sin juzgar, la agilidad mental y la calidez fraterna en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega Cuento Colectivo?</h2>
<p>Para llevar a cabo la dinámica con alegría, mística y fluidas intervenciones, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Preparación del Círculo Narrativo:</b> La unidad se sienta en un círculo estrecho para favorecer la acústica y el clima de fogata. Se coloca el mazo de tarjetas boca abajo al centro.</li>
  <li><b>Inicio del Primer Capítulo:</b> El primer scout saca la primera tarjeta y da comienzo a la aventura (ej. <i>''En una noche estrellada en el campamento Nua Mana...''</i>), introduciendo a los personajes principales.</li>
  <li><b>Relato Encadenado a Tiempo Límite:</b> Cada scout por turno roba una tarjeta, disponiendo de un máximo de 10 segundos para acoplar su palabra a la historia y transmitir la palabra al siguiente participante.</li>
  <li><b>Giro Dramático de Patrulla:</b> Si el relato se estanca, el dirigente o guía puede gritar <i>''¡Giro inesperado!''</i> introduciendo un evento sorpresa al que la patrulla debe reaccionar.</li>
  <li><b>Desenlace y Bitácora:</b> El último scout del círculo concluye la historia. Un dirigente lee el resumen anotado en la bitácora para que la patrulla disfrute la aventura creada comunitariamente.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Cuento Colectivo</h2>
<p>La actividad valora la creatividad verbal, la soltura narrativa y el espíritu de acogida en el Tally:</p>
<ul>
  <li><b>Mayor Coherencia y Fluidez:</b> Otorgar 5 puntos a la patrulla que teja el argumento con mejor hilación y sentido del humor.</li>
  <li><b>Integración Rápida de Palabras Clave:</b> Otorgar 3 puntos al equipo que acople las tarjetas sin vacilaciones ni pausas largas.</li>
  <li><b>Expresividad y Matices de Voz:</b> Otorgar 3 puntos al grupo que interprete a sus personajes con emoción y caracterización.</li>
</ul>', '/uploads/cuento-colectivo.webp', 'publicado', '{"areas": ["creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Cartulina"], "objetivos": ["Estimular la creatividad", "Fomentar las opiniones personales", "Fomentar la comunicación e interpretación", "Crear un clima de pertenencia"], "justificacion_areas": "Cuento Colectivo potencia la creatividad al exigir la asociación inmediata de ideas abstractas y la construcción de estructuras narrativas imaginativas. Desarrolla la afectividad al construir un clima de acogida, escucha atenta y valorización de las ocurrencias de cada participante en fogata desde Manada hasta Clan.", "variaciones": "<b>Cuentos con Objetos Misteriosos de Mochila:</b> En lugar de tarjetas, sacar elementos reales de la mochila de campamento (brújula, linterna, cordín).<br><b>Cuentos de Género Variable:</b> Cambiar el género narrativo en cada ronda (comedia, suspenso, aventura épica).<br><b>Cuentos Ilustrados en Bitácora:</b> Dibujar la historia en el cuaderno de patrulla a medida que se relata.", "recomendaciones": "Evitar descalificar las ocurrencias fantásticas de los lobatos. Estimular la escucha respetuosa durante todo el relato.", "objetivos_educativos": [{"id": "897408de-c314-4908-aee0-4a0e0e56d4ba", "area": "Creatividad", "unidad": "Manada", "texto": "Converso con los demás sobre las cosas que me llaman la atención.", "como_se_cumple": "Compartiendo con entusiasmo ideas y frases para la historia colectiva."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Creando un ambiente de afecto y apoyo a las ocurrencias de los compañeros."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "area": "Creatividad", "unidad": "Manada", "texto": "Trato de hablar claro y conocer nuevas palabras.", "como_se_cumple": "Expresando con claridad las frases del cuento encadenado."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Respetando las ideas de los lobatos al continuar el relato."}, {"id": "0d742d23-ebe1-40e6-97df-37bc03edb010", "area": "Creatividad", "unidad": "Compañía", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Expresando vivencias y relatos fantásticos en la creación oral."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención y valoración los giros narrativos de las pares."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Compañía", "texto": "Me gusta actuar y expresarme.", "como_se_cumple": "Dramatizando las frases de la historia con voces e intenciones."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Fomentando un clima de confianza afectiva e integración en la ronda."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "como_se_cumple": "Diseñando tramas y desenlaces ingeniosos para el cuento de Tropa."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Respetando y encadenando con fluidez los aportes de todos."}, {"id": "9758e4f9-728b-4435-a8a3-11fd36c5e3be", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Demostrando soltura narrativa y riqueza de vocabulario scout."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Afianzando la mística y la fraternidad en el fuego de campamento."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo creaciones literarias y relatos de reflexión en Avanzada."}, {"id": "3b32ea2c-da58-487c-bea4-e02f301f5e3e", "area": "Afectividad", "unidad": "Avanzada", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Construyendo espacios afectivos de expresión sincera sin inhibiciones."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando la narrativa mística y la fraternidad en el Clan Rover."}, {"id": "d0ba748f-313b-4ffe-b2a3-fb21c1f8943f", "area": "Afectividad", "unidad": "Clan", "texto": "Practica una conducta asertiva y una actitud afectuosa hacia las demás personas, sin inhibiciones ni agresividad.", "como_se_cumple": "Promoviendo la hermandad alegre y el clima de hogar en el Clan."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

